type Lookup = { id: string; code: string; nameFa: string; nameEn?: string; isActive: boolean }
type Reference = Lookup & { referenceType: string; sortOrder: number; version: number }
type Lookups = { currencies: Lookup[]; suppliers: Lookup[]; references: Reference[]; referenceTypes: string[] }
type ReferenceList = { items: Reference[]; page: number; pageSize: number; totalCount: number }
type Project = { id: string; projectNumber: string; titleFa: string; titleEn?: string; customerNameFa?: string; customerNameEn?: string; supplierName?: string; priority: string; status: string; targetDate?: string; version: number; updatedAtUtc: string }
type ProjectList = { items: Project[]; page: number; pageSize: number; totalCount: number }
type OrderRegistration = { id: string; registrationNumber: string; status: string; registrationDate: string; registeredAmount: number; currencyCode: string; notes?: string; version: number }
type Fx = { id: string; processType: string; dealStatus: string; receiptStatus: string; amount: number; currencyCode: string; bankNameFa?: string; bankNameEn?: string; requestDate: string; allocationDate?: string; referenceNumber?: string; version: number }
type Leg = { id: string; sequence: number; fromLocation: string; toLocation: string; status: string; estimatedDeparture?: string; estimatedArrival?: string; actualDeparture?: string; actualArrival?: string; trackingNumber?: string; version: number }
type Shipment = { id: string; shipmentNumber: string; status: string; transportMode: string; forwarderNameFa?: string; forwarderNameEn?: string; origin: string; destination: string; estimatedDeparture?: string; estimatedArrival?: string; actualDeparture?: string; actualArrival?: string; grossWeight?: number; volumeCbm?: number; notes?: string; version: number; legs: Leg[] }
type ShipmentLink = { linkId: string; allocationMethod: string; allocationValue: number; notes?: string; version: number; shipment: Shipment; customs: Customs[] }
type Customs = { id: string; clearanceNumber: string; clearanceType: string; status: string; customsOfficeNameFa?: string; customsOfficeNameEn?: string; declarationDate?: string; releaseDate?: string; version: number }
type Cost = { id: string; scopeType: string; scopeId: string; costType: string; amount: number; currencyCode: string; effectiveDate: string; referenceNumber?: string; isVoided: boolean }
type Audit = { id: string; actorUserId: string; action: string; reason?: string; occurredAtUtc: string }
type ProjectCapabilities = { canViewOrders: boolean; canViewFx: boolean; canViewShipments: boolean; canViewCustoms: boolean; canViewCosts: boolean; canViewAudit: boolean }
type ProjectDetail = { project: Project; notes?: string; orderRegistrations: OrderRegistration[]; fxAllocations: Fx[]; shipments: ShipmentLink[]; costs: Cost[]; audit: Audit[]; capabilities: ProjectCapabilities }
type ProjectContext = { id: string; projectNumber: string; titleFa: string; titleEn?: string }
type ShipmentWorklist = { items: Array<{ shipment: Shipment; projects: ProjectContext[] }>; page: number; pageSize: number; totalCount: number }
type CustomsWorklist = { items: Array<{ customs: Customs; shipmentNumber: string; projects: ProjectContext[] }>; page: number; pageSize: number; totalCount: number }
type CostWorklist = { items: Array<{ cost: Cost; project: ProjectContext }>; page: number; pageSize: number; totalCount: number }
type ReportWorklist = { items: Array<{ project: Project; orderRegistrationCount: number; fxAllocationCount: number; shipmentCount: number; customsCount: number; costTotals: Array<{ currencyCode: string; currencyNameFa: string; currencyNameEn?: string; amount: number }> }>; page: number; pageSize: number; totalCount: number }
type TradingStatusTarget = { kind: 'ORDER'; value: OrderRegistration } | { kind: 'FX'; value: Fx } | { kind: 'LEG'; value: Leg } | { kind: 'CUSTOMS'; value: Customs }

const emptyProject = { titleFa: '', titleEn: '', customerId: '', supplierId: '', priority: 'NORMAL', targetDate: '', notes: '' }
const statusTone = (status: string) => status.includes('CANCEL') ? 'critical' : status.includes('CLOSED') || status.includes('DELIVERED') || status.includes('COMPLETE') ? 'positive' : status.includes('DRAFT') || status.includes('NOT_') ? 'neutral' : 'information'
const display = (fa: string | undefined, en: string | undefined, language: string) => language.startsWith('en') ? en || fa || '—' : fa || '—'
const codeLabel = (translate: ReturnType<typeof useTranslation>['t'], code: string) => translate(`trading.codes.${code}`, { defaultValue: code })
const tradingDateInput = (value: string | undefined, language: string) => !value || language.startsWith('en')
  ? value ?? ''
  : toAsciiDigits(formatBusinessDate(value, 'fa-IR')).replace(/[^0-9]/g, '')

async function canonicalTradingDate(value: string | undefined, language: string, required = false) {
  if (!value?.trim()) { if (required) throw new Error(language.startsWith('en') ? 'Business date is required.' : 'تاریخ کسب‌وکار الزامی است.'); return null }
  if (language.startsWith('en')) return value
  const normalized = normalizeJalaliDateInput(value)
  if (!normalized) throw new Error('تاریخ شمسی باید ۸ رقم و به‌صورت YYYYMMDD باشد.')
  const response = await fetch(`${apiRoot}/planning/resolve-jalali-date`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ jalaliDate: normalized }) })
  if (!response.ok) throw new Error('تاریخ شمسی معتبر نیست.')
  return (await response.json() as { gregorianDate: string }).gregorianDate
}

async function request<T>(path: string, method = 'GET', body?: unknown): Promise<T> {
  const response = await fetch(`${apiRoot}/trading${path}`, { method, headers: body ? { 'Content-Type': 'application/json' } : undefined, body: body ? JSON.stringify(body) : undefined })
  if (!response.ok) {
    const problem = await response.json().catch(() => null) as { detail?: string; title?: string; errors?: Record<string, string[]> } | null
    throw new Error(problem?.detail ?? Object.values(problem?.errors ?? {})[0]?.[0] ?? problem?.title ?? `HTTP ${response.status}`)
  }
  return response.status === 204 ? undefined as T : response.json() as Promise<T>
}

const TRADING_FLOW_STEPS = [
  { key: 'createProject', icon: Plus },
  { key: 'orderRegistrations', icon: ClipboardList },
  { key: 'fxOperations', icon: CircleDollarSign },
  { key: 'shipments', icon: Container },
  { key: 'transportStages', icon: Truck },
  { key: 'customs', icon: FileCheck2 },
] as const

export function TradingOverviewPage() {
  const { t, i18n } = useTranslation(); const language = i18n.resolvedLanguage ?? i18n.language
  const [activeStep, setActiveStep] = useState(0)
  const ActiveStepIcon = TRADING_FLOW_STEPS[activeStep].icon
  return <main><PageHeader eyebrow={t('trading.eyebrow')} title={t('trading.title')} subtitle={t('trading.subtitle')} />
    <Section title={t('trading.flow.title')} description={t('trading.flow.description')}>
      <ol className="trading-flow-steps" aria-label={t('trading.flow.stepsLabel')}>
        {TRADING_FLOW_STEPS.map((step, index) => {
          const StepIcon = step.icon
          return <li key={step.key}>
            <button type="button" className={`trading-flow-step${index === activeStep ? ' is-active' : ''}${index < activeStep ? ' is-done' : ''}`} aria-current={index === activeStep ? 'step' : undefined} onClick={() => setActiveStep(index)}>
              <b aria-hidden="true">{number(index + 1, language)}</b>
              <StepIcon aria-hidden="true" />
              <span>{t(`trading.flow.steps.${step.key}`)}</span>
            </button>
          </li>
        })}
      </ol>
      <div className="trading-flow-panel">
        <div className="trading-flow-panel__head">
          <span className="trading-flow-panel__icon"><ActiveStepIcon aria-hidden="true" /></span>
          <div>
            <strong>{t(`trading.flow.steps.${TRADING_FLOW_STEPS[activeStep].key}`)}</strong>
            <small>{t('trading.flow.stepOf', { current: number(activeStep + 1, language), total: number(TRADING_FLOW_STEPS.length, language) })}</small>
          </div>
        </div>
        <p className="trading-flow-panel__placeholder">{t('trading.flow.contentPlaceholder')}</p>
        <div className="trading-flow-nav">
          <button type="button" className="button" disabled={activeStep === 0} onClick={() => setActiveStep(step => step - 1)}>{t('common.previous')}</button>
          <button type="button" className="button button--primary" disabled={activeStep === TRADING_FLOW_STEPS.length - 1} onClick={() => setActiveStep(step => step + 1)}>{t('common.next')}</button>
        </div>
      </div>
    </Section>
  </main>
}

export function TradeProjectListPage() {
  const { t, i18n } = useTranslation(); const language = i18n.resolvedLanguage ?? i18n.language
  const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [page, setPage] = useState(1); const [data, setData] = useState<ProjectList | null>(null); const [error, setError] = useState('')
  const load = useCallback(() => { const qs = new URLSearchParams({ page: String(page), pageSize: '25' }); if (search.trim()) qs.set('search', search.trim()); if (status) qs.set('status', status); request<ProjectList>(`/projects?${qs}`).then(value => { setError(''); setData(value) }).catch(e => setError(e.message)) }, [page, search, status])
  useEffect(load, [load])
  return <main><PageHeader eyebrow={t('trading.eyebrow')} title={t('trading.projects')} subtitle={t('trading.projectsHint')} actions={<Link className="button button--primary" to="/trading/projects/new"><Plus />{t('trading.newProject')}</Link>} />
    {error && <MessageStrip tone="critical">{error}</MessageStrip>}
    <FilterBar label={t('common.filters')}><FormField label={t('common.search')}><div className="ui-search-field"><Search /><input value={search} onChange={e => { setPage(1); setSearch(e.target.value) }} placeholder={t('trading.searchProject')} /></div></FormField><FormField label={t('common.status')}><select value={status} onChange={e => { setPage(1); setStatus(e.target.value) }}><option value="">{t('common.all')}</option>{['DRAFT','ACTIVE','WAITING_ORDER','FX_PROCESS','READY_TO_SHIP','IN_TRANSIT','IN_CUSTOMS','CLEARED','DELIVERED','CLOSED','CANCELLED'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField></FilterBar>
    <Section title={t('trading.projectWorklist')}><ProjectTable projects={data?.items ?? []} language={language} loading={!data && !error} filtered={Boolean(search || status)} />{data && <Pagination page={page} pageSize={data.pageSize} totalCount={data.totalCount} onPageChange={setPage} previousLabel={t('common.previous')} nextLabel={t('common.next')} summary={t('common.paginationSummary', { page, count: data.totalCount })} />}</Section>
  </main>
}

function ProjectTable({ projects, language, loading, filtered = false }: { projects: Project[]; language: string; loading?: boolean; filtered?: boolean }) {
  const { t } = useTranslation()
  return <DataTable headers={[t('trading.projectNumber'), t('trading.project'), t('trading.partyContext'), t('trading.targetDate'), t('common.status')]} loading={loading} empty={!projects.length} filtered={filtered} loadingLabel={t('common.loading')} emptyTitle={t('trading.noProjects')} noResultTitle={t('common.noResultsTitle')}>
    <>{projects.map(project => <tr key={project.id}><td><Link to={`/trading/projects/${project.id}`}><bdi>{project.projectNumber}</bdi></Link></td><td><strong>{display(project.titleFa, project.titleEn, language)}</strong><small>{codeLabel(t, project.priority)}</small></td><td>{display(project.customerNameFa, project.customerNameEn, language)}<small>{project.supplierName ?? '—'}</small></td><td>{formatBusinessDate(project.targetDate, language)}</td><td><StatusBadge text={codeLabel(t, project.status)} tone={statusTone(project.status)} /></td></tr>)}</>
  </DataTable>
}

export function TradeProjectCreatePage() {
  const { t, i18n } = useTranslation(); const navigate = useNavigate(); const language = i18n.resolvedLanguage ?? i18n.language
  const [form, setForm] = useState(emptyProject); const [lookups, setLookups] = useState<Lookups | null>(null); const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  const dirty = useFormDirty(form); const safeCancel = useSafeCancel(dirty, () => navigate('/trading/projects'))
  useEffect(() => { request<Lookups>('/lookups').then(setLookups).catch(e => setError(e.message)) }, [])
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); setError(''); try { const data = await request<ProjectDetail>('/projects', 'POST', { ...form, customerId: form.customerId || null, supplierId: form.supplierId || null, targetDate: await canonicalTradingDate(form.targetDate, language) }); navigate(`/trading/projects/${data.project.id}`) } catch (e) { setError((e as Error).message) } finally { setSaving(false) } }
  const customers = lookups?.references.filter(x => x.referenceType === 'CUSTOMER') ?? []
  return <main><PageHeader eyebrow={t('trading.eyebrow')} title={t('trading.newProject')} subtitle={t('trading.generatedNumber')} backTo="/trading/projects" backLabel={t('common.backToList')} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}<Section title={t('trading.projectIdentity')}><form className="ui-object-form" onSubmit={submit}><div className="ui-form-grid ui-form-grid--3"><FormField label={t('common.nameFa')} required><input required value={form.titleFa} onChange={e => setForm({ ...form, titleFa: e.target.value })} /></FormField><FormField label={t('common.nameEn')}><input dir="ltr" value={form.titleEn} onChange={e => setForm({ ...form, titleEn: e.target.value })} /></FormField><FormField label={t('trading.priority')}><select value={form.priority} onChange={e => setForm({ ...form, priority: e.target.value })}>{['LOW','NORMAL','HIGH','CRITICAL'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField><FormField label={t('trading.customer')}><select value={form.customerId} onChange={e => setForm({ ...form, customerId: e.target.value })}><option value="">—</option>{customers.map(x => <option key={x.id} value={x.id}>{display(x.nameFa, x.nameEn, language)}</option>)}</select></FormField><FormField label={t('trading.supplier')}><select value={form.supplierId} onChange={e => setForm({ ...form, supplierId: e.target.value })}><option value="">—</option>{lookups?.suppliers.map(x => <option key={x.id} value={x.id}>{x.code} — {display(x.nameFa, x.nameEn, language)}</option>)}</select></FormField><TradingDateField label={t('trading.targetDate')} value={form.targetDate} language={language} onChange={targetDate => setForm({ ...form, targetDate })} /><FormField className="span-2" label={t('common.notes')}><textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /></FormField></div><div className="ui-form-actions"><button className="button button--primary" disabled={saving}>{saving ? t('common.saving') : t('common.save')}</button><button className="button" type="button" onClick={safeCancel}>{t('common.cancel')}</button></div></form></Section></main>
}

export function TradeProjectObjectPage() {
  const { id = '' } = useParams(); const { t, i18n } = useTranslation(); const { has } = useAuth(); const language = i18n.resolvedLanguage ?? i18n.language
  const [data, setData] = useState<ProjectDetail | null>(null); const [lookups, setLookups] = useState<Lookups | null>(null); const [error, setError] = useState(''); const [operation, setOperation] = useState<'ORDER'|'FX'|'SHIPMENT'|'COST'|null>(null)
  const [projectAction, setProjectAction] = useState<'EDIT'|'STATUS'|'REOPEN'|null>(null); const [shipmentAction, setShipmentAction] = useState<{ type: 'LEG'|'CUSTOMS'|'ACTUAL'; shipment: Shipment } | null>(null)
  const [linkShipment, setLinkShipment] = useState(false); const [allocationLink, setAllocationLink] = useState<ShipmentLink | null>(null)
  const [statusTarget, setStatusTarget] = useState<TradingStatusTarget | null>(null)
  const load = useCallback(() => { Promise.all([request<ProjectDetail>(`/projects/${id}`), request<Lookups>('/lookups')]).then(([detail, refs]) => { setError(''); setData(detail); setLookups(refs) }).catch(e => setError(e.message)) }, [id])
  useEffect(load, [load])
  if (!data && !error) return <main><PageHeader title={t('trading.project')} /><Section title={t('common.loading')}><div /></Section></main>
  if (!data) return <main><MessageStrip tone="critical">{error}</MessageStrip></main>
  const project = data.project; const operational = !['CLOSED','CANCELLED'].includes(project.status)
  const canManageProject = has('trading.project.manage'); const canManageOrder = has('trading.order_registration.manage')
  const canManageFx = has('trading.fx.manage'); const canManageShipment = has('trading.shipment.manage')
  const canManageCustoms = has('trading.customs.manage'); const canManageCost = has('trading.cost.manage')
  return <main><PageHeader eyebrow={project.projectNumber} title={display(project.titleFa, project.titleEn, language)} subtitle={t('trading.objectHint')} status={<StatusBadge text={codeLabel(t, project.status)} tone={statusTone(project.status)} />} backTo="/trading/projects" backLabel={t('common.backToList')} actions={<div className="ui-inline-actions">{canManageProject && operational && <button className="button" onClick={() => setProjectAction('EDIT')}>{t('common.edit')}</button>}{has('trading.project.close') && operational && <button className="button" onClick={() => setProjectAction('STATUS')}>{t('trading.changeStatus')}</button>}{has('trading.project.reopen') && project.status === 'CLOSED' && <button className="button" onClick={() => setProjectAction('REOPEN')}>{t('trading.reopenProject')}</button>}<button className="button" onClick={load}><RefreshCw />{t('common.refresh')}</button></div>} />
    {error && <MessageStrip tone="critical">{error}</MessageStrip>}
    <section className="trading-process-rail" aria-label={t('trading.lifecycle')}>{['PROJECT','ORDER','FX','SHIPMENT','CUSTOMS','COST'].map((step, index) => <span className={(index === 0 || data.orderRegistrations.length && index === 1 || data.fxAllocations.length && index === 2 || data.shipments.length && index === 3 || data.shipments.some(x => x.customs.length) && index === 4 || data.costs.length && index === 5) ? 'complete' : ''} key={step}><b>{index + 1}</b>{t(`trading.steps.${step}`)}</span>)}</section>
    <Section title={t('trading.projectContext')} actions={operational && <div className="ui-inline-actions">{canManageOrder && <button className="button" onClick={() => setOperation('ORDER')}>{t('trading.addOrder')}</button>}{canManageFx && <button className="button" onClick={() => setOperation('FX')}>{t('trading.addFx')}</button>}{canManageShipment && <><button className="button" onClick={() => setOperation('SHIPMENT')}>{t('trading.addShipment')}</button><button className="button" onClick={() => setLinkShipment(true)}>{t('trading.linkShipment')}</button></>}{canManageCost && <button className="button" onClick={() => setOperation('COST')}>{t('trading.addCost')}</button>}</div>}><DefinitionGrid><Definition label={t('trading.customer')}>{display(project.customerNameFa, project.customerNameEn, language)}</Definition><Definition label={t('trading.supplier')}>{project.supplierName ?? '—'}</Definition><Definition label={t('trading.priority')}>{codeLabel(t, project.priority)}</Definition><Definition label={t('trading.targetDate')}>{formatBusinessDate(project.targetDate, language)}</Definition></DefinitionGrid>{data.notes && <p className="trading-note">{data.notes}</p>}</Section>
    {projectAction && <TradingProjectActionForm action={projectAction} project={project} notes={data.notes} language={language} onDone={() => { setProjectAction(null); load() }} onCancel={() => setProjectAction(null)} onError={setError} />}
    {operation && lookups && <TradingOperationForm operation={operation} project={project} data={data} lookups={lookups} language={language} onDone={() => { setOperation(null); load() }} onCancel={() => setOperation(null)} onError={setError} />}
    {shipmentAction && lookups && <TradingShipmentActionForm action={shipmentAction.type} shipment={shipmentAction.shipment} lookups={lookups} language={language} onDone={() => { setShipmentAction(null); load() }} onCancel={() => setShipmentAction(null)} onError={setError} />}
    {linkShipment && <TradingLinkShipmentForm project={project} linkedShipmentIds={data.shipments.map(x => x.shipment.id)} language={language} onDone={() => { setLinkShipment(false); load() }} onCancel={() => setLinkShipment(false)} onError={setError} />}
    {allocationLink && <TradingAllocationForm link={allocationLink} language={language} onDone={() => { setAllocationLink(null); load() }} onCancel={() => setAllocationLink(null)} onError={setError} />}
    {statusTarget && <TradingRecordStatusForm target={statusTarget} language={language} onDone={() => { setStatusTarget(null); load() }} onCancel={() => setStatusTarget(null)} onError={setError} />}
    <ProjectOperationalSections data={data} language={language} operational={operational} canManageOrder={canManageOrder} canManageFx={canManageFx} canManageShipment={canManageShipment} canManageCustoms={canManageCustoms} onStatus={setStatusTarget} onShipmentAction={(type, shipment) => setShipmentAction({ type, shipment })} onAllocation={setAllocationLink} />
  </main>
}

function TradingProjectActionForm({ action, project, notes, language, onDone, onCancel, onError }: { action: 'EDIT'|'STATUS'|'REOPEN'; project: Project; notes?: string; language: string; onDone: () => void; onCancel: () => void; onError: (value: string) => void }) {
  const { t } = useTranslation(); const [saving, setSaving] = useState(false); const [form, setForm] = useState({ titleFa: project.titleFa, titleEn: project.titleEn ?? '', priority: project.priority, targetDate: tradingDateInput(project.targetDate, language), notes: notes ?? '', status: project.status, reason: '', isCorrection: false })
  const dirty = useFormDirty(form); const safeCancel = useSafeCancel(dirty, onCancel)
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); onError(''); try { if (action === 'EDIT') await request(`/projects/${project.id}`, 'PUT', { titleFa: form.titleFa, titleEn: form.titleEn || null, priority: form.priority, targetDate: await canonicalTradingDate(form.targetDate, language), notes: form.notes || null, expectedVersion: project.version }); else if (action === 'REOPEN') await request(`/projects/${project.id}/reopen`, 'POST', { expectedVersion: project.version, reason: form.reason }); else await request(`/projects/${project.id}/status`, 'POST', { status: form.status, expectedVersion: project.version, reason: form.reason, isCorrection: form.isCorrection }); onDone() } catch (e) { onError((e as Error).message) } finally { setSaving(false) } }
  const projectStatusOptions = [project.status, ...tradingStatusOptions('PROJECT', project.status, form.isCorrection)]
  return <Section title={action === 'EDIT' ? t('trading.editProject') : action === 'REOPEN' ? t('trading.reopenProject') : t('trading.changeStatus')}><form onSubmit={submit}><div className="ui-form-grid ui-form-grid--3">{action === 'EDIT' ? <><FormField label={t('common.nameFa')} required><input required value={form.titleFa} onChange={e => setForm({ ...form, titleFa: e.target.value })} /></FormField><FormField label={t('common.nameEn')}><input dir="ltr" value={form.titleEn} onChange={e => setForm({ ...form, titleEn: e.target.value })} /></FormField><FormField label={t('trading.priority')}><select value={form.priority} onChange={e => setForm({ ...form, priority: e.target.value })}>{['LOW','NORMAL','HIGH','CRITICAL'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField><TradingDateField label={t('trading.targetDate')} value={form.targetDate} language={language} onChange={targetDate => setForm({ ...form, targetDate })} /><FormField className="span-2" label={t('common.notes')}><textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /></FormField></> : <>{action === 'STATUS' && <><FormField label={t('common.status')} required><select value={form.status} onChange={e => setForm({ ...form, status: e.target.value })}>{projectStatusOptions.map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField><FormField label={t('trading.correction')}><label className="ui-check"><input type="checkbox" checked={form.isCorrection} onChange={e => setForm({ ...form, isCorrection: e.target.checked })} />{t('trading.correctionHint')}</label></FormField></>}<FormField className="span-2" label={t('common.reason')} required><input required value={form.reason} onChange={e => setForm({ ...form, reason: e.target.value })} /></FormField></>}</div><div className="ui-form-actions"><button className="button button--primary" disabled={saving}>{t('common.save')}</button><button className="button" type="button" onClick={safeCancel}>{t('common.cancel')}</button></div></form></Section>
}

function TradingRecordStatusForm({ target, language, onDone, onCancel, onError }: { target: TradingStatusTarget; language: string; onDone: () => void; onCancel: () => void; onError: (value: string) => void }) {
  const { t } = useTranslation(); const [saving, setSaving] = useState(false)
  const initial: Record<string, string> = target.kind === 'ORDER' ? { status: target.value.status } : target.kind === 'FX'
    ? { processType: target.value.processType, dealStatus: target.value.dealStatus, receiptStatus: target.value.receiptStatus, allocationDate: tradingDateInput(target.value.allocationDate, language), notes: '' }
    : target.kind === 'LEG' ? { status: target.value.status, departureDate: tradingDateInput(target.value.actualDeparture, language), arrivalDate: tradingDateInput(target.value.actualArrival, language), notes: '' }
    : { status: target.value.status, releaseDate: tradingDateInput(target.value.releaseDate, language), notes: '' }
  const [form, setForm] = useState<Record<string, string>>({ ...initial, reason: '', isCorrection: 'false' })
  const dirty = useFormDirty(form); const safeCancel = useSafeCancel(dirty, onCancel)
  const set = (key: string, next: string) => setForm(current => ({ ...current, [key]: next }))
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setSaving(true); onError('')
    try {
      const isCorrection = form.isCorrection === 'true'
      if (target.kind === 'ORDER') await request(`/order-registrations/${target.value.id}/status`, 'POST', { status: form.status, expectedVersion: target.value.version, reason: form.reason, isCorrection })
      if (target.kind === 'FX') await request(`/fx-allocations/${target.value.id}/status`, 'POST', { processType: form.processType, dealStatus: form.dealStatus, receiptStatus: form.receiptStatus, allocationDate: await canonicalTradingDate(form.allocationDate, language), notes: form.notes || null, expectedVersion: target.value.version, reason: form.reason, isCorrection })
      if (target.kind === 'LEG') await request(`/shipment-legs/${target.value.id}/status`, 'POST', { status: form.status, actualDeparture: await canonicalTradingDate(form.departureDate, language), actualArrival: await canonicalTradingDate(form.arrivalDate, language), notes: form.notes || null, expectedVersion: target.value.version, reason: form.reason, isCorrection })
      if (target.kind === 'CUSTOMS') await request(`/customs-clearances/${target.value.id}/status`, 'POST', { status: form.status, releaseDate: await canonicalTradingDate(form.releaseDate, language), notes: form.notes || null, expectedVersion: target.value.version, reason: form.reason, isCorrection })
      onDone()
    } catch (error) { onError((error as Error).message) } finally { setSaving(false) }
  }
  const correction = form.isCorrection === 'true'
  const options = target.kind === 'ORDER' ? [target.value.status, ...tradingStatusOptions('ORDER', target.value.status, correction)] : target.kind === 'LEG'
    ? [target.value.status, ...tradingStatusOptions('LEG', target.value.status, correction)] : target.kind === 'CUSTOMS'
      ? [target.value.status, ...tradingStatusOptions('CUSTOMS', target.value.status, correction)] : []
  const fxOptions = (sequence: string[], current: string, correctionEnabled: boolean) => [current, ...tradingLinearOptions(sequence, current, correctionEnabled)]
  return <Section title={t('trading.changeOperationalStatus')}><form onSubmit={submit}><div className="ui-form-grid ui-form-grid--3">
    {target.kind !== 'FX' && <StatusSelect value={form.status} onChange={next => set('status', next)} options={options} />}
    {target.kind === 'FX' && <><FormField label={t('trading.processType')}><select value={form.processType} onChange={event => set('processType', event.target.value)}>{fxOptions(['REQUEST','ALLOCATION','DEAL','RECEIPT'], target.value.processType, correction).concat(correction ? ['CORRECTION'] : []).filter((value, index, values) => values.indexOf(value) === index).map(code => <option key={code} value={code}>{codeLabel(t, code)}</option>)}</select></FormField><FormField label={t('trading.dealStatus')}><select value={form.dealStatus} onChange={event => set('dealStatus', event.target.value)}>{fxOptions(['NOT_STARTED','IN_QUEUE','PRIORITY_CONFIRMED','ALLOCATED','DEAL_DONE'], target.value.dealStatus, correction).map(code => <option key={code} value={code}>{codeLabel(t, code)}</option>)}</select></FormField><FormField label={t('trading.receiptStatus')}><select value={form.receiptStatus} onChange={event => set('receiptStatus', event.target.value)}>{fxOptions(['NOT_RECEIVED','PARTIAL','COMPLETE'], target.value.receiptStatus, correction).map(code => <option key={code} value={code}>{codeLabel(t, code)}</option>)}</select></FormField><TradingDateField label={t('trading.allocationDate')} value={form.allocationDate} language={language} onChange={next => set('allocationDate', next)} /></>}
    {target.kind === 'LEG' && <><TradingDateField label={t('trading.actualDeparture')} value={form.departureDate} language={language} onChange={next => set('departureDate', next)} /><TradingDateField label={t('trading.actualArrival')} value={form.arrivalDate} language={language} onChange={next => set('arrivalDate', next)} /></>}
    {target.kind === 'CUSTOMS' && <TradingDateField label={t('trading.releaseDate')} value={form.releaseDate} language={language} onChange={next => set('releaseDate', next)} />}
    <FormField label={t('trading.correction')}><label className="ui-check"><input type="checkbox" checked={form.isCorrection === 'true'} onChange={event => set('isCorrection', String(event.target.checked))} />{t('trading.correctionHint')}</label></FormField>
    <FormField className="span-2" label={t('common.reason')} required><input required value={form.reason} onChange={event => set('reason', event.target.value)} /></FormField>
    {target.kind !== 'ORDER' && <FormField className="span-2" label={t('common.notes')}><textarea value={form.notes} onChange={event => set('notes', event.target.value)} /></FormField>}
  </div><div className="ui-form-actions"><button className="button button--primary" disabled={saving}>{t('common.save')}</button><button className="button" type="button" onClick={safeCancel}>{t('common.cancel')}</button></div></form></Section>
}

function TradingOperationForm({ operation, project, data, lookups, language, onDone, onCancel, onError }: { operation: 'ORDER'|'FX'|'SHIPMENT'|'COST'; project: Project; data: ProjectDetail; lookups: Lookups; language: string; onDone: () => void; onCancel: () => void; onError: (value: string) => void }) {
  const { t } = useTranslation(); const [saving, setSaving] = useState(false)
  const [form, setForm] = useState<Record<string, string>>({ status: operation === 'ORDER' ? 'DRAFT' : operation === 'SHIPMENT' ? 'DRAFT' : '', processType: 'REQUEST', dealStatus: 'NOT_STARTED', receiptStatus: 'NOT_RECEIVED', transportMode: 'SEA', allocationMethod: 'EQUAL', scopeType: 'PROJECT', scopeId: project.id, projectId: project.id })
  const dirty = useFormDirty(form); const safeCancel = useSafeCancel(dirty, onCancel)
  const refs = (type: string) => lookups.references.filter(x => x.referenceType === type)
  const set = (key: string, value: string) => setForm(current => ({ ...current, [key]: value }))
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); onError(''); try {
    if (operation === 'ORDER') await request('/order-registrations', 'POST', { projectId: project.id, registrationNumber: form.registrationNumber, status: 'DRAFT', registrationDate: await canonicalTradingDate(form.date, language, true), registeredAmount: Number(form.amount), currencyId: form.currencyId, notes: form.notes || null })
    if (operation === 'FX') await request('/fx-allocations', 'POST', { projectId: project.id, orderRegistrationId: form.orderRegistrationId || null, processType: 'REQUEST', dealStatus: 'NOT_STARTED', receiptStatus: 'NOT_RECEIVED', amount: Number(form.amount), currencyId: form.currencyId, bankId: form.bankId || null, requestDate: await canonicalTradingDate(form.date, language, true), allocationDate: null, referenceNumber: form.referenceNumber || null, notes: form.notes || null })
    if (operation === 'SHIPMENT') await request('/shipments', 'POST', { projectId: project.id, status: 'DRAFT', transportMode: form.transportMode, forwarderId: form.forwarderId || null, origin: form.origin, destination: form.destination, estimatedDeparture: await canonicalTradingDate(form.date, language), estimatedArrival: await canonicalTradingDate(form.arrivalDate, language), grossWeight: form.grossWeight ? Number(form.grossWeight) : null, volumeCbm: form.volumeCbm ? Number(form.volumeCbm) : null, allocationMethod: form.allocationMethod, allocationValue: Number(form.allocationValue || 0), notes: form.notes || null })
    if (operation === 'COST') await request('/costs', 'POST', { projectId: project.id, scopeType: form.scopeType, scopeId: form.scopeId || project.id, costType: form.costType, amount: Number(form.amount), currencyId: form.currencyId, effectiveDate: await canonicalTradingDate(form.date, language, true), referenceNumber: form.referenceNumber || null, notes: form.notes || null })
    onDone()
  } catch (e) { onError((e as Error).message) } finally { setSaving(false) } }
  return <Section title={t(`trading.operation.${operation}`)} description={t('trading.operationHint')}><form onSubmit={submit}><div className="ui-form-grid ui-form-grid--3">
    {operation === 'ORDER' && <><FormField label={t('trading.registrationNumber')} required><input required dir="ltr" value={form.registrationNumber ?? ''} onChange={e => set('registrationNumber', e.target.value)} /></FormField><FormField label={t('common.status')}><input disabled value={codeLabel(t, 'DRAFT')} /></FormField><MoneyFields form={form} set={set} lookups={lookups} language={language} /><TradingDateField label={t('trading.businessDate')} required value={form.date} language={language} onChange={x => set('date', x)} /></>}
    {operation === 'FX' && <><FormField label={t('trading.orderRegistration')}><select value={form.orderRegistrationId ?? ''} onChange={e => set('orderRegistrationId', e.target.value)}><option value="">—</option>{data.orderRegistrations.map(x => <option key={x.id} value={x.id}>{x.registrationNumber}</option>)}</select></FormField><FormField label={t('trading.processType')}><input disabled value={codeLabel(t, 'REQUEST')} /></FormField><FormField label={t('trading.bank')}><select value={form.bankId ?? ''} onChange={e => set('bankId', e.target.value)}><option value="">—</option>{refs('BANK').map(x => <option key={x.id} value={x.id}>{display(x.nameFa, x.nameEn, language)}</option>)}</select></FormField><MoneyFields form={form} set={set} lookups={lookups} language={language} /><TradingDateField label={t('trading.businessDate')} required value={form.date} language={language} onChange={x => set('date', x)} /><FormField label={t('trading.dealStatus')}><input disabled value={codeLabel(t, 'NOT_STARTED')} /></FormField></>}
    {operation === 'SHIPMENT' && <><FormField label={t('common.status')}><input disabled value={codeLabel(t, 'DRAFT')} /></FormField><FormField label={t('trading.transportMode')}><select value={form.transportMode} onChange={e => set('transportMode', e.target.value)}>{['SEA','AIR','ROAD','RAIL','MULTIMODAL'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField><FormField label={t('trading.forwarder')}><select value={form.forwarderId ?? ''} onChange={e => set('forwarderId', e.target.value)}><option value="">—</option>{refs('FORWARDER').map(x => <option key={x.id} value={x.id}>{display(x.nameFa, x.nameEn, language)}</option>)}</select></FormField><FormField label={t('trading.origin')} required><input required value={form.origin ?? ''} onChange={e => set('origin', e.target.value)} /></FormField><FormField label={t('trading.destination')} required><input required value={form.destination ?? ''} onChange={e => set('destination', e.target.value)} /></FormField><TradingDateField label={t('trading.departureDate')} value={form.date} language={language} onChange={x => set('date', x)} /><TradingDateField label={t('trading.arrivalDate')} value={form.arrivalDate} language={language} onChange={x => set('arrivalDate', x)} /><FormField label={t('trading.grossWeight')}><input type="number" min="0" step="any" value={form.grossWeight ?? ''} onChange={e => set('grossWeight', e.target.value)} /></FormField><FormField label={t('trading.volumeCbm')}><input type="number" min="0" step="any" value={form.volumeCbm ?? ''} onChange={e => set('volumeCbm', e.target.value)} /></FormField></>}
    {operation === 'COST' && <><FormField label={t('trading.costType')} required><input required value={form.costType ?? ''} onChange={e => set('costType', e.target.value)} /></FormField><MoneyFields form={form} set={set} lookups={lookups} language={language} /><TradingDateField label={t('trading.businessDate')} required value={form.date} language={language} onChange={x => set('date', x)} /></>}
    <FormField className="span-2" label={t('common.notes')}><textarea value={form.notes ?? ''} onChange={e => set('notes', e.target.value)} /></FormField>
  </div><div className="ui-form-actions"><button className="button button--primary" disabled={saving}>{saving ? t('common.saving') : t('common.save')}</button><button type="button" className="button" onClick={safeCancel}>{t('common.cancel')}</button></div></form></Section>
}

function MoneyFields({ form, set, lookups, language }: { form: Record<string,string>; set: (key: string, value: string) => void; lookups: Lookups; language: string }) { const { t } = useTranslation(); return <><FormField label={t('trading.amount')} required><input required type="number" min="0.000001" step="any" value={form.amount ?? ''} onChange={e => set('amount', e.target.value)} /></FormField><FormField label={t('trading.currency')} required><select required value={form.currencyId ?? ''} onChange={e => set('currencyId', e.target.value)}><option value="">—</option>{lookups.currencies.map(x => <option key={x.id} value={x.id}>{x.code} — {display(x.nameFa, x.nameEn, language)}</option>)}</select></FormField></> }
function TradingDateField({ label, value, language, required = false, onChange }: { label: string; value?: string; language: string; required?: boolean; onChange: (value: string) => void }) {
  return <FormField label={label} required={required}><input required={required} type={language.startsWith('en') ? 'date' : 'text'} inputMode={language.startsWith('en') ? undefined : 'numeric'} dir="ltr" maxLength={language.startsWith('en') ? undefined : 10} placeholder={language.startsWith('en') ? undefined : 'YYYYMMDD'} value={value ?? ''} onChange={event => onChange(language.startsWith('en') ? event.target.value : toAsciiDigits(event.target.value).replace(/[^0-9/-]/g, ''))} /></FormField>
}
function useFormDirty(form: unknown) {
  const [initial] = useState(() => JSON.stringify(form))
  const dirty = initial !== JSON.stringify(form)
  useEffect(() => {
    if (!dirty) return
    const protect = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = '' }
    window.addEventListener('beforeunload', protect)
    return () => window.removeEventListener('beforeunload', protect)
  }, [dirty])
  return dirty
}
function useSafeCancel(dirty: boolean, onCancel: () => void) {
  const { t } = useTranslation()
  return () => { if (!dirty || window.confirm(t('trading.unsavedConfirm'))) onCancel() }
}
function StatusSelect({ value, onChange, options }: { value: string; onChange: (value: string) => void; options: string[] }) { const { t } = useTranslation(); return <FormField label={t('common.status')}><select value={value} onChange={e => onChange(e.target.value)}>{options.map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField> }

function TradingShipmentActionForm({ action, shipment, lookups, language, onDone, onCancel, onError }: { action: 'LEG'|'CUSTOMS'|'ACTUAL'; shipment: Shipment; lookups: Lookups; language: string; onDone: () => void; onCancel: () => void; onError: (value: string) => void }) {
  const { t } = useTranslation(); const [saving, setSaving] = useState(false); const [form, setForm] = useState<Record<string, string>>({ sequence: String(shipment.legs.length + 1), transportMode: shipment.transportMode, status: action === 'LEG' ? 'PLANNED' : action === 'CUSTOMS' ? 'NOT_STARTED' : shipment.status, clearanceType: 'DEFINITIVE', departureDate: tradingDateInput(shipment.actualDeparture, language), arrivalDate: tradingDateInput(shipment.actualArrival, language), isCorrection: 'false', notes: shipment.notes ?? '' })
  const dirty = useFormDirty(form); const safeCancel = useSafeCancel(dirty, onCancel)
  const set = (key: string, value: string) => setForm(current => ({ ...current, [key]: value }))
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); onError(''); try { if (action === 'LEG') await request(`/shipments/${shipment.id}/legs`, 'POST', { sequence: Number(form.sequence), fromLocation: form.fromLocation, toLocation: form.toLocation, transportMode: form.transportMode, status: 'PLANNED', estimatedDeparture: await canonicalTradingDate(form.departureDate, language), estimatedArrival: await canonicalTradingDate(form.arrivalDate, language), trackingNumber: form.trackingNumber || null, notes: form.notes || null }); if (action === 'CUSTOMS') await request('/customs-clearances', 'POST', { shipmentId: shipment.id, clearanceNumber: form.clearanceNumber, clearanceType: form.clearanceType, status: 'NOT_STARTED', customsOfficeId: form.customsOfficeId || null, declarationDate: await canonicalTradingDate(form.departureDate, language), releaseDate: await canonicalTradingDate(form.arrivalDate, language), notes: form.notes || null }); if (action === 'ACTUAL') await request(`/shipments/${shipment.id}/actuals`, 'PUT', { status: form.status, actualDeparture: await canonicalTradingDate(form.departureDate, language), actualArrival: await canonicalTradingDate(form.arrivalDate, language), notes: form.notes || null, expectedVersion: shipment.version, reason: form.reason, isCorrection: form.isCorrection === 'true' }); onDone() } catch (e) { onError((e as Error).message) } finally { setSaving(false) } }
  return <Section title={`${shipment.shipmentNumber} — ${t(`trading.operation.${action}`)}`}><form onSubmit={submit}><div className="ui-form-grid ui-form-grid--3">{action === 'LEG' && <><FormField label={t('trading.legSequence')} required><input required type="number" min="1" value={form.sequence} onChange={e => set('sequence', e.target.value)} /></FormField><FormField label={t('trading.origin')} required><input required value={form.fromLocation ?? ''} onChange={e => set('fromLocation', e.target.value)} /></FormField><FormField label={t('trading.destination')} required><input required value={form.toLocation ?? ''} onChange={e => set('toLocation', e.target.value)} /></FormField><FormField label={t('trading.transportMode')}><select value={form.transportMode} onChange={e => set('transportMode', e.target.value)}>{['SEA','AIR','ROAD','RAIL','MULTIMODAL'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField><FormField label={t('common.status')}><input disabled value={codeLabel(t, 'PLANNED')} /></FormField><FormField label={t('trading.trackingNumber')}><input dir="ltr" value={form.trackingNumber ?? ''} onChange={e => set('trackingNumber', e.target.value)} /></FormField></>}{action === 'CUSTOMS' && <><FormField label={t('trading.clearanceNumber')} required><input required dir="ltr" value={form.clearanceNumber ?? ''} onChange={e => set('clearanceNumber', e.target.value)} /></FormField><FormField label={t('trading.clearanceType')} required><select required value={form.clearanceType} onChange={e => set('clearanceType', e.target.value)}>{['DEFINITIVE','TEMPORARY','TRANSIT','RETURN'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField><FormField label={t('common.status')}><input disabled value={codeLabel(t, 'NOT_STARTED')} /></FormField><FormField label={t('trading.customsOffice')}><select value={form.customsOfficeId ?? ''} onChange={e => set('customsOfficeId', e.target.value)}><option value="">—</option>{lookups.references.filter(x => x.referenceType === 'CUSTOMS_OFFICE').map(x => <option key={x.id} value={x.id}>{display(x.nameFa, x.nameEn, language)}</option>)}</select></FormField></>}{action === 'ACTUAL' && <><StatusSelect value={form.status} onChange={x => set('status', x)} options={[shipment.status, ...tradingStatusOptions('SHIPMENT', shipment.status, form.isCorrection === 'true')]} /><TradingDateField label={t('trading.actualDeparture')} value={form.departureDate} language={language} onChange={x => set('departureDate', x)} /><TradingDateField label={t('trading.actualArrival')} value={form.arrivalDate} language={language} onChange={x => set('arrivalDate', x)} /><FormField label={t('trading.correction')}><label className="ui-check"><input type="checkbox" checked={form.isCorrection === 'true'} onChange={event => set('isCorrection', String(event.target.checked))} />{t('trading.correctionHint')}</label></FormField><FormField className="span-2" label={t('common.reason')} required><input required value={form.reason ?? ''} onChange={e => set('reason', e.target.value)} /></FormField></>}{action !== 'ACTUAL' && <><TradingDateField label={t('trading.departureDate')} value={form.departureDate} language={language} onChange={x => set('departureDate', x)} /><TradingDateField label={t(action === 'CUSTOMS' ? 'trading.releaseDate' : 'trading.arrivalDate')} value={form.arrivalDate} language={language} onChange={x => set('arrivalDate', x)} /></>}<FormField className="span-2" label={t('common.notes')}><textarea value={form.notes ?? ''} onChange={e => set('notes', e.target.value)} /></FormField></div><div className="ui-form-actions"><button className="button button--primary" disabled={saving}>{t('common.save')}</button><button className="button" type="button" onClick={safeCancel}>{t('common.cancel')}</button></div></form></Section>
}

function TradingLinkShipmentForm({ project, linkedShipmentIds, language, onDone, onCancel, onError }: { project: Project; linkedShipmentIds: string[]; language: string; onDone: () => void; onCancel: () => void; onError: (value: string) => void }) {
  const { t } = useTranslation(); const [search, setSearch] = useState(''); const [shipments, setShipments] = useState<ShipmentWorklist | null>(null); const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({ shipmentId: '', allocationMethod: 'EQUAL', allocationValue: '0', notes: '' }); const dirty = useFormDirty(form); const safeCancel = useSafeCancel(dirty, onCancel)
  useEffect(() => { const timer = window.setTimeout(() => { const qs = new URLSearchParams({ page: '1', pageSize: '25' }); if (search.trim()) qs.set('search', search.trim()); request<ShipmentWorklist>(`/shipments?${qs}`).then(setShipments).catch(error => onError(error.message)) }, 250); return () => window.clearTimeout(timer) }, [search, onError])
  const available = shipments?.items.filter(x => !linkedShipmentIds.includes(x.shipment.id)) ?? []
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); onError(''); try { await request(`/shipments/${form.shipmentId}/projects`, 'POST', { projectId: project.id, allocationMethod: form.allocationMethod, allocationValue: Number(form.allocationValue), notes: form.notes || null }); onDone() } catch (error) { onError((error as Error).message) } finally { setSaving(false) } }
  return <Section title={t('trading.linkShipment')} description={t('trading.linkShipmentHint')}><form onSubmit={submit}><div className="ui-form-grid ui-form-grid--3"><FormField label={t('common.search')}><input value={search} onChange={event => setSearch(event.target.value)} placeholder={t('trading.shipmentSearch')} /></FormField><FormField label={t('trading.shipmentNumber')} required><select required value={form.shipmentId} onChange={event => setForm({ ...form, shipmentId: event.target.value })}><option value="">—</option>{available.map(x => <option key={x.shipment.id} value={x.shipment.id}>{x.shipment.shipmentNumber} — {x.shipment.origin} / {x.shipment.destination}</option>)}</select></FormField><AllocationFields form={form} setForm={setForm} language={language} /><FormField className="span-2" label={t('common.notes')}><textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></FormField></div><div className="ui-form-actions"><button className="button button--primary" disabled={saving || !form.shipmentId}>{t('common.save')}</button><button className="button" type="button" onClick={safeCancel}>{t('common.cancel')}</button></div></form></Section>
}

function TradingAllocationForm({ link, language, onDone, onCancel, onError }: { link: ShipmentLink; language: string; onDone: () => void; onCancel: () => void; onError: (value: string) => void }) {
  const { t } = useTranslation(); const [saving, setSaving] = useState(false); const [form, setForm] = useState({ allocationMethod: link.allocationMethod, allocationValue: String(link.allocationValue), notes: link.notes ?? '', reason: '' }); const dirty = useFormDirty(form); const safeCancel = useSafeCancel(dirty, onCancel)
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); onError(''); try { await request(`/project-shipments/${link.linkId}`, 'PUT', { allocationMethod: form.allocationMethod, allocationValue: Number(form.allocationValue), notes: form.notes || null, expectedVersion: link.version, reason: form.reason }); onDone() } catch (error) { onError((error as Error).message) } finally { setSaving(false) } }
  return <Section title={`${link.shipment.shipmentNumber} — ${t('trading.editAllocation')}`}><form onSubmit={submit}><div className="ui-form-grid ui-form-grid--3"><AllocationFields form={form} setForm={setForm} language={language} /><FormField label={t('common.reason')} required><input required value={form.reason} onChange={event => setForm({ ...form, reason: event.target.value })} /></FormField><FormField className="span-2" label={t('common.notes')}><textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></FormField></div><div className="ui-form-actions"><button className="button button--primary" disabled={saving}>{t('common.save')}</button><button className="button" type="button" onClick={safeCancel}>{t('common.cancel')}</button></div></form></Section>
}

function AllocationFields<T extends { allocationMethod: string; allocationValue: string }>({ form, setForm, language }: { form: T; setForm: (value: T) => void; language: string }) {
  const { t } = useTranslation(); return <><FormField label={t('trading.allocationMethod')}><select value={form.allocationMethod} onChange={event => setForm({ ...form, allocationMethod: event.target.value })}>{['GOODS_VALUE','CBM','WEIGHT','COUNT','MANUAL_PERCENT','EQUAL'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}</select></FormField><FormField label={t('trading.allocationValue')} required><input required type="number" min="0" step="any" lang={language.startsWith('en') ? 'en' : 'fa'} value={form.allocationValue} onChange={event => setForm({ ...form, allocationValue: event.target.value })} /></FormField></>
}

function ProjectOperationalSections({ data, language, operational, canManageOrder, canManageFx, canManageShipment, canManageCustoms, onStatus, onShipmentAction, onAllocation }: { data: ProjectDetail; language: string; operational: boolean; canManageOrder: boolean; canManageFx: boolean; canManageShipment: boolean; canManageCustoms: boolean; onStatus: (target: TradingStatusTarget) => void; onShipmentAction: (type: 'LEG'|'CUSTOMS'|'ACTUAL', shipment: Shipment) => void; onAllocation: (link: ShipmentLink) => void }) {
  const { t } = useTranslation()
  const shipmentRows = useMemo(() => data.shipments.flatMap(link => [{ link, shipment: link.shipment }]), [data.shipments])
  return <div className="trading-object-sections">
    {data.capabilities.canViewOrders && <Section title={t('trading.orderRegistrations')}><DataTable headers={[t('trading.registrationNumber'), t('trading.businessDate'), t('trading.amount'), t('common.status'), t('common.actions')]} empty={!data.orderRegistrations.length} loadingLabel={t('common.loading')} emptyTitle={t('trading.noOrders')} noResultTitle={t('common.noResultsTitle')}><>{data.orderRegistrations.map(x => <tr key={x.id}><td><bdi>{x.registrationNumber}</bdi></td><td>{formatBusinessDate(x.registrationDate, language)}</td><td>{number(x.registeredAmount, language)} <bdi>{x.currencyCode}</bdi></td><td><StatusBadge text={codeLabel(t, x.status)} tone={statusTone(x.status)} /></td><td>{operational && canManageOrder && <button className="button button--compact" type="button" onClick={() => onStatus({ kind: 'ORDER', value: x })}>{t('trading.changeOperationalStatus')}</button>}</td></tr>)}</></DataTable></Section>}
    {data.capabilities.canViewFx && <Section title={t('trading.fx')}><DataTable headers={[t('trading.processType'), t('trading.amount'), t('trading.bank'), t('common.status'), t('common.actions')]} empty={!data.fxAllocations.length} loadingLabel={t('common.loading')} emptyTitle={t('trading.noFx')} noResultTitle={t('common.noResultsTitle')}><>{data.fxAllocations.map(x => <tr key={x.id}><td>{codeLabel(t, x.processType)}<small>{formatBusinessDate(x.requestDate, language)}</small></td><td>{number(x.amount, language)} <bdi>{x.currencyCode}</bdi></td><td>{display(x.bankNameFa, x.bankNameEn, language)}</td><td><StatusBadge text={`${codeLabel(t, x.dealStatus)} / ${codeLabel(t, x.receiptStatus)}`} tone={statusTone(x.dealStatus)} /></td><td>{operational && canManageFx && <button className="button button--compact" type="button" onClick={() => onStatus({ kind: 'FX', value: x })}>{t('trading.changeOperationalStatus')}</button>}</td></tr>)}</></DataTable></Section>}
    {data.capabilities.canViewShipments && <Section title={t('trading.shipments')}><DataTable headers={[t('trading.shipmentNumber'), t('trading.route'), t('trading.eta'), t('trading.allocation'), t('common.status'), t('common.actions')]} empty={!shipmentRows.length} loadingLabel={t('common.loading')} emptyTitle={t('trading.noShipments')} noResultTitle={t('common.noResultsTitle')}><>{shipmentRows.map(({ link, shipment }) => <tr key={link.linkId}><td><bdi>{shipment.shipmentNumber}</bdi><small>{codeLabel(t, shipment.transportMode)} · {shipment.legs.length} {t('trading.legs')}</small></td><td>{shipment.origin} ← {shipment.destination}</td><td>{formatBusinessDate(shipment.estimatedArrival, language)}</td><td>{codeLabel(t, link.allocationMethod)} · {number(link.allocationValue, language)}</td><td><StatusBadge text={codeLabel(t, shipment.status)} tone={statusTone(shipment.status)} /></td><td><div className="ui-inline-actions">{operational && canManageShipment && <><button className="button button--compact" type="button" onClick={() => onAllocation(link)}>{t('trading.editAllocation')}</button><button className="button button--compact" type="button" onClick={() => onShipmentAction('LEG', shipment)}>{t('trading.addLeg')}</button><button className="button button--compact" type="button" onClick={() => onShipmentAction('ACTUAL', shipment)}>{t('trading.updateActuals')}</button></>}{operational && canManageCustoms && data.capabilities.canViewCustoms && <button className="button button--compact" type="button" onClick={() => onShipmentAction('CUSTOMS', shipment)}>{t('trading.addCustoms')}</button>}</div></td></tr>)}</></DataTable>{shipmentRows.flatMap(({ shipment }) => shipment.legs.map(leg => <article className="trading-leg-card" key={leg.id}><bdi>{shipment.shipmentNumber} / {leg.sequence}</bdi><span>{leg.fromLocation} ← {leg.toLocation}</span><span>{formatBusinessDate(leg.estimatedDeparture, language)} — {formatBusinessDate(leg.estimatedArrival, language)}</span><StatusBadge text={codeLabel(t, leg.status)} tone={statusTone(leg.status)} />{operational && canManageShipment && <button className="button button--compact" type="button" onClick={() => onStatus({ kind: 'LEG', value: leg })}>{t('trading.changeOperationalStatus')}</button>}</article>))}{data.capabilities.canViewCustoms && shipmentRows.flatMap(({ link, shipment }) => link.customs.map(clearance => <article className="trading-leg-card" key={clearance.id}><bdi>{shipment.shipmentNumber} / {clearance.clearanceNumber}</bdi><span>{codeLabel(t, clearance.clearanceType)}</span><span>{formatBusinessDate(clearance.declarationDate, language)} — {formatBusinessDate(clearance.releaseDate, language)}</span><StatusBadge text={codeLabel(t, clearance.status)} tone={statusTone(clearance.status)} />{operational && canManageCustoms && <button className="button button--compact" type="button" onClick={() => onStatus({ kind: 'CUSTOMS', value: clearance })}>{t('trading.changeOperationalStatus')}</button>}</article>))}</Section>}
    {data.capabilities.canViewCosts && <Section title={t('trading.costs')}><DataTable headers={[t('trading.costType'), t('trading.amount'), t('trading.businessDate'), t('common.status')]} empty={!data.costs.length} loadingLabel={t('common.loading')} emptyTitle={t('trading.noCosts')} noResultTitle={t('common.noResultsTitle')}><>{data.costs.map(x => <tr key={x.id}><td>{x.costType}<small>{codeLabel(t, x.scopeType)}</small></td><td>{number(x.amount, language)} <bdi>{x.currencyCode}</bdi></td><td>{formatBusinessDate(x.effectiveDate, language)}</td><td><StatusBadge text={x.isVoided ? t('trading.voided') : t('trading.valid')} tone={x.isVoided ? 'critical' : 'positive'} /></td></tr>)}</></DataTable></Section>}
    {data.capabilities.canViewAudit && <Section title={t('trading.audit')} description={t('trading.auditHint')}><>{data.audit.length ? <ol className="trading-audit-list">{data.audit.map(x => <li key={x.id}><strong>{codeLabel(t, x.action)}</strong><span>{formatBusinessDateTime(x.occurredAtUtc, language)}</span>{x.reason && <p>{x.reason}</p>}</li>)}</ol> : <EmptyState title={t('trading.noAudit')} />}</></Section>}
  </div>
}

export function TradingPerspectivePage({ perspective }: { perspective: 'shipments'|'customs'|'costs'|'reports' }) {
  const { t, i18n } = useTranslation(); const language = i18n.resolvedLanguage ?? i18n.language
  const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [page, setPage] = useState(1)
  const [data, setData] = useState<ShipmentWorklist | CustomsWorklist | CostWorklist | ReportWorklist | null>(null)
  const [error, setError] = useState('')
  const path = perspective === 'customs' ? 'customs-clearances' : perspective
  const load = useCallback(() => {
    const qs = buildTradingPerspectiveQuery(perspective, page, 25, search, status)
    request<ShipmentWorklist | CustomsWorklist | CostWorklist | ReportWorklist>(`/${path}?${qs}`).then(value => { setError(''); setData(value) }).catch(e => setError(e.message))
  }, [page, path, perspective, search, status])
  useEffect(load, [load])
  const total = data?.totalCount ?? 0
  return <main><PageHeader eyebrow={t('trading.eyebrow')} title={t(`trading.${perspective}`)} subtitle={t('trading.perspectiveHint')} actions={<button className="button" type="button" onClick={load}><RefreshCw />{t('common.refresh')}</button>} />
    {error && <MessageStrip tone="critical">{error}</MessageStrip>}
    <FilterBar label={t('common.filters')}><FormField label={t('common.search')}><div className="ui-search-field"><Search /><input value={search} onChange={event => { setPage(1); setSearch(event.target.value) }} placeholder={t('trading.searchOperational')} /></div></FormField><FormField label={t('common.status')}><select value={status} onChange={event => { setPage(1); setStatus(event.target.value) }}><option value="">{perspective === 'costs' ? t('trading.validOnly') : t('common.all')}</option>{perspective === 'shipments' && ['DRAFT','WAITING_LINK','READY','IN_TRANSIT','ARRIVED','IN_CUSTOMS','PARTIAL_CLEARED','CLEARED','DELIVERED','CANCELLED'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}{perspective === 'customs' && ['NOT_STARTED','DOCUMENTS_PENDING','IN_PROGRESS','PARTIAL','COMPLETE','BLOCKED','CANCELLED'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}{perspective === 'reports' && ['DRAFT','ACTIVE','WAITING_ORDER','FX_PROCESS','READY_TO_SHIP','IN_TRANSIT','IN_CUSTOMS','CLEARED','DELIVERED','CLOSED','CANCELLED'].map(x => <option key={x} value={x}>{codeLabel(t, x)}</option>)}{perspective === 'costs' && <option value="ALL">{t('trading.includeVoided')}</option>}</select></FormField></FilterBar>
    <Section title={t(`trading.${perspective}`)}>
      {perspective === 'shipments' && <ShipmentPerspective rows={(data as ShipmentWorklist | null)?.items ?? []} language={language} />}
      {perspective === 'customs' && <CustomsPerspective rows={(data as CustomsWorklist | null)?.items ?? []} language={language} />}
      {perspective === 'costs' && <CostPerspective rows={(data as CostWorklist | null)?.items ?? []} language={language} />}
      {perspective === 'reports' && <ReportPerspective rows={(data as ReportWorklist | null)?.items ?? []} language={language} />}
      <Pagination page={page} pageSize={data?.pageSize ?? 25} totalCount={total} onPageChange={setPage} previousLabel={t('common.previous')} nextLabel={t('common.next')} summary={t('common.paginationSummary', { page, count: total })} />
    </Section>
  </main>
}

function ProjectLinks({ projects, language }: { projects: ProjectContext[]; language: string }) {
  return <>{projects.map(project => <Link className="trading-project-link" key={project.id} to={`/trading/projects/${project.id}`}><bdi>{project.projectNumber}</bdi><small>{display(project.titleFa, project.titleEn, language)}</small></Link>)}</>
}

function ShipmentPerspective({ rows, language }: { rows: ShipmentWorklist['items']; language: string }) {
  const { t } = useTranslation(); return <DataTable headers={[t('trading.shipmentNumber'), t('trading.projects'), t('trading.route'), t('trading.eta'), t('common.status')]} empty={!rows.length} loadingLabel={t('common.loading')} emptyTitle={t('trading.noShipments')} noResultTitle={t('common.noResultsTitle')}><>{rows.map(row => <tr key={row.shipment.id}><td><bdi>{row.shipment.shipmentNumber}</bdi><small>{codeLabel(t, row.shipment.transportMode)} · {row.shipment.legs.length} {t('trading.legs')}</small></td><td><ProjectLinks projects={row.projects} language={language} /></td><td>{row.shipment.origin} ← {row.shipment.destination}</td><td>{formatBusinessDate(row.shipment.estimatedArrival, language)}</td><td><StatusBadge text={codeLabel(t, row.shipment.status)} tone={statusTone(row.shipment.status)} /></td></tr>)}</></DataTable>
}

function CustomsPerspective({ rows, language }: { rows: CustomsWorklist['items']; language: string }) {
  const { t } = useTranslation(); return <DataTable headers={[t('trading.clearanceNumber'), t('trading.shipmentNumber'), t('trading.projects'), t('trading.releaseDate'), t('common.status')]} empty={!rows.length} loadingLabel={t('common.loading')} emptyTitle={t('trading.noCustoms')} noResultTitle={t('common.noResultsTitle')}><>{rows.map(row => <tr key={row.customs.id}><td><bdi>{row.customs.clearanceNumber}</bdi><small>{codeLabel(t, row.customs.clearanceType)}</small></td><td><bdi>{row.shipmentNumber}</bdi></td><td><ProjectLinks projects={row.projects} language={language} /></td><td>{formatBusinessDate(row.customs.releaseDate, language)}</td><td><StatusBadge text={codeLabel(t, row.customs.status)} tone={statusTone(row.customs.status)} /></td></tr>)}</></DataTable>
}

function CostPerspective({ rows, language }: { rows: CostWorklist['items']; language: string }) {
  const { t } = useTranslation(); return <DataTable headers={[t('trading.project'), t('trading.costType'), t('trading.amount'), t('trading.businessDate'), t('common.status')]} empty={!rows.length} loadingLabel={t('common.loading')} emptyTitle={t('trading.noCosts')} noResultTitle={t('common.noResultsTitle')}><>{rows.map(row => <tr key={row.cost.id}><td><ProjectLinks projects={[row.project]} language={language} /></td><td>{row.cost.costType}<small>{codeLabel(t, row.cost.scopeType)}</small></td><td>{number(row.cost.amount, language)} <bdi>{row.cost.currencyCode}</bdi></td><td>{formatBusinessDate(row.cost.effectiveDate, language)}</td><td><StatusBadge text={row.cost.isVoided ? t('trading.voided') : t('trading.valid')} tone={row.cost.isVoided ? 'critical' : 'positive'} /></td></tr>)}</></DataTable>
}

function ReportPerspective({ rows, language }: { rows: ReportWorklist['items']; language: string }) {
  const { t } = useTranslation(); return <DataTable headers={[t('trading.project'), t('trading.orderRegistrations'), t('trading.fx'), t('trading.shipments'), t('trading.customs'), t('trading.originalCurrencyTotals')]} empty={!rows.length} loadingLabel={t('common.loading')} emptyTitle={t('trading.noProjects')} noResultTitle={t('common.noResultsTitle')}><>{rows.map(row => <tr key={row.project.id}><td><ProjectLinks projects={[row.project]} language={language} /><StatusBadge text={codeLabel(t, row.project.status)} tone={statusTone(row.project.status)} /></td><td>{number(row.orderRegistrationCount, language)}</td><td>{number(row.fxAllocationCount, language)}</td><td>{number(row.shipmentCount, language)}</td><td>{number(row.customsCount, language)}</td><td>{row.costTotals.length ? row.costTotals.map(total => <span className="trading-currency-total" key={total.currencyCode}>{number(total.amount, language)} <bdi>{total.currencyCode}</bdi></span>) : '—'}</td></tr>)}</></DataTable>
}

export function TradingReferencePage() {
  const { t } = useTranslation()
  const [data, setData] = useState<Lookups | null>(null); const [list, setList] = useState<ReferenceList | null>(null); const [editing, setEditing] = useState<Reference | null>(null)
  const [form, setForm] = useState({ referenceType: '', nameFa: '', nameEn: '', sortOrder: '0' }); const [reason, setReason] = useState('')
  const [stateTarget, setStateTarget] = useState<Reference | null>(null); const [error, setError] = useState(''); const [saving, setSaving] = useState(false); const [page, setPage] = useState(1); const [search, setSearch] = useState(''); const [typeFilter, setTypeFilter] = useState('')
  const dirty = useFormDirty(form); const reset = () => { setEditing(null); setForm({ referenceType: data?.referenceTypes[0] ?? '', nameFa: '', nameEn: '', sortOrder: '0' }) }; const safeReset = useSafeCancel(dirty, reset)
  const load = useCallback(() => { const qs = new URLSearchParams({ includeInactive: 'true', page: String(page), pageSize: '25' }); if (search.trim()) qs.set('search', search.trim()); if (typeFilter) qs.set('referenceType', typeFilter); Promise.all([request<Lookups>('/lookups?includeInactive=true&limit=100'), request<ReferenceList>(`/references?${qs}`)]).then(([lookups, references]) => { setError(''); setData(lookups); setList(references); setForm(current => ({ ...current, referenceType: current.referenceType || lookups.referenceTypes[0] || '' })) }).catch(e => setError(e.message)) }, [page, search, typeFilter])
  useEffect(load, [load])
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); setError(''); try { if (editing) await request(`/references/${editing.id}`, 'PUT', { nameFa: form.nameFa, nameEn: form.nameEn || null, sortOrder: Number(form.sortOrder), expectedVersion: editing.version }); else await request('/references', 'POST', { referenceType: form.referenceType, nameFa: form.nameFa, nameEn: form.nameEn || null, sortOrder: Number(form.sortOrder) }); reset(); load() } catch (e) { setError((e as Error).message) } finally { setSaving(false) } }
  const changeState = async () => { if (!stateTarget || !reason.trim()) return; setSaving(true); setError(''); try { await request(`/references/${stateTarget.id}/state`, 'POST', { isActive: !stateTarget.isActive, expectedVersion: stateTarget.version, reason }); setStateTarget(null); setReason(''); load() } catch (e) { setError((e as Error).message) } finally { setSaving(false) } }
  return <main><PageHeader eyebrow={t('trading.eyebrow')} title={t('trading.references')} subtitle={t('trading.referencesHint')} />{error && <MessageStrip tone="critical">{error}</MessageStrip>}
    <Section title={editing ? t('common.edit') : t('trading.newReference')}><form onSubmit={submit}><div className="ui-form-grid ui-form-grid--3"><FormField label={t('trading.referenceType')} required><select required disabled={Boolean(editing)} value={form.referenceType} onChange={e => setForm({ ...form, referenceType: e.target.value })}>{data?.referenceTypes.map(type => <option key={type} value={type}>{codeLabel(t, type)}</option>)}</select></FormField><FormField label={t('common.nameFa')} required><input required value={form.nameFa} onChange={e => setForm({ ...form, nameFa: e.target.value })} /></FormField><FormField label={t('common.nameEn')}><input dir="ltr" value={form.nameEn} onChange={e => setForm({ ...form, nameEn: e.target.value })} /></FormField><FormField label={t('trading.sortOrder')}><input type="number" min="0" value={form.sortOrder} onChange={e => setForm({ ...form, sortOrder: e.target.value })} /></FormField></div><div className="ui-form-actions"><button className="button button--primary" disabled={saving}>{t('common.save')}</button>{editing && <button className="button" type="button" onClick={safeReset}>{t('common.cancel')}</button>}</div></form></Section>
    {stateTarget && <Section title={stateTarget.isActive ? t('trading.deactivateReference') : t('trading.reactivateReference')}><div className="ui-inline-form"><FormField label={t('common.reason')} required><input autoFocus value={reason} onChange={e => setReason(e.target.value)} /></FormField><button className="button button--primary" disabled={!reason.trim() || saving} type="button" onClick={() => void changeState()}>{t('common.confirm')}</button><button className="button" type="button" onClick={() => { setStateTarget(null); setReason('') }}>{t('common.cancel')}</button></div></Section>}
    <FilterBar label={t('common.filters')}><FormField label={t('common.search')}><input value={search} onChange={event => { setPage(1); setSearch(event.target.value) }} /></FormField><FormField label={t('trading.referenceType')}><select value={typeFilter} onChange={event => { setPage(1); setTypeFilter(event.target.value) }}><option value="">{t('common.all')}</option>{data?.referenceTypes.map(type => <option key={type} value={type}>{codeLabel(t, type)}</option>)}</select></FormField></FilterBar>
    <Section title={t('trading.references')}><DataTable headers={[t('trading.referenceType'), t('common.code'), t('common.nameFa'), t('common.nameEn'), t('common.status'), t('common.actions')]} empty={!list?.items.length} loading={!list && !error} filtered={Boolean(search || typeFilter)} loadingLabel={t('common.loading')} emptyTitle={t('trading.noReferences')} noResultTitle={t('common.noResultsTitle')}><>{list?.items.map(row => <tr key={row.id}><td>{codeLabel(t, row.referenceType)}</td><td><bdi>{row.code}</bdi></td><td>{row.nameFa}</td><td dir="ltr">{row.nameEn ?? '—'}</td><td><StatusBadge text={row.isActive ? t('common.active') : t('common.inactive')} tone={row.isActive ? 'positive' : 'neutral'} /></td><td><div className="ui-inline-actions"><button className="button button--compact" type="button" onClick={() => { setEditing(row); setForm({ referenceType: row.referenceType, nameFa: row.nameFa, nameEn: row.nameEn ?? '', sortOrder: String(row.sortOrder) }); window.scrollTo({ top: 0, behavior: 'smooth' }) }}>{t('common.edit')}</button><button className="button button--compact" type="button" onClick={() => setStateTarget(row)}>{row.isActive ? t('common.deactivate') : t('common.reactivate')}</button></div></td></tr>)}</></DataTable>{list && <Pagination page={page} pageSize={list.pageSize} totalCount={list.totalCount} onPageChange={setPage} previousLabel={t('common.previous')} nextLabel={t('common.next')} summary={t('common.paginationSummary', { page, count: list.totalCount })} />}</Section>
    <MessageStrip>{t('trading.referencesOwnershipHint')}</MessageStrip>
  </main>
}
